import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第六卦 讼 天水讼 乾上坎下","description":"周易 - 第六卦 讼 天水讼 乾上坎下","frontmatter":{"title":"第六卦 讼 天水讼 乾上坎下","description":"周易 - 第六卦 讼 天水讼 乾上坎下"},"headers":[],"relativePath":"zh/classics/zhouyi/007.md","filePath":"zh/classics/zhouyi/007.md"}'),l={name:"zh/classics/zhouyi/007.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="讼" tabindex="-1">讼 <a class="header-anchor" href="#讼" aria-label="Permalink to “讼”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>有孚，窒。惕中吉。终凶。利见大人，不利涉大川。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>讼，上刚下险，险而健讼。讼有孚窒，惕中吉，刚来而得中也。终凶；讼不可成也。利见大人；尚中正也。不利涉大川；入于渊也。</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>天与水违行，讼；君子以作事谋始。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>不永所事，小有言，终吉。象曰：不 永所事，讼不可长也。虽有小言，其辩明也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>不克讼，归而逋，其邑人三百户，无眚。象曰：不克讼，归而逋也。自下讼上，患至掇也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>食旧德，贞厉，终吉，或从王事，无成。象曰：食旧德，从上吉也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>不克讼，复自命，渝安贞，吉。象曰：复即命，渝安贞；不失也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>讼元吉。象曰：讼元吉，以中正也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>或锡之鞶带，终朝三褫之。象曰：以讼受服，亦不足敬也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
